// "DUKUN vs DEMIT" -- a procedural Halloween horror featurette (~3 minutes).
// Every asset is generated by code: visuals from rmtn/draw.hpp primitives, the score
// from rmtn/synth.hpp sine-sum events, and rain/wind/screech from code-generated WAVs.
//
//   raymotion_halloween list
//   raymotion_halloween preview dukun-vs-demit
//   raymotion_halloween render  dukun-vs-demit      -> out/dukun-vs-demit.mp4
//   raymotion_halloween still   dukun-vs-demit --at 1550
#include "rmtn/raymotion.hpp"

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <string>
#include <vector>

using namespace rmtn;

namespace {

using V2 = Vector2;

constexpr float W = 1280, H = 720;
constexpr int FPS = 30;
constexpr int TR = 22;                    // transition overlap between shots, frames
constexpr unsigned long long SEED = 19741101;
const std::string AUDIO_DIR = "out/hw-audio-v1";

// ------------------------------------------------------------------ palette
const Color NIGHT_TOP  = mkColor(0x04050e);
const Color NIGHT_BOT  = mkColor(0x150a1e);
const Color SILHOUETTE = mkColor(0x0a0612);
const Color BONE       = mkColor(0xe8e2d0);
const Color DEMIT_RED  = mkColor(0xff2b18);
const Color FLAME      = mkColor(0xffb347);
const Color DUKUN_COL  = mkColor(0x241b44);
const Color MOON_RED   = mkColor(0xff5030);

// ================================================================== ambience
// Lightning flash envelope: decays over ~5 frames after each strike.
float flashAt(int t, unsigned long long salt) {
    float f = 0;
    for (int k = 0; k < 20; k++) {
        double ef = 8 + k * 46 + rrange(SEED, salt * 31 + k, 0, 30);
        double d = (double)t - ef;
        if (d >= 0 && d < 6) f = std::max(f, (float)std::exp(-d * 1.4));
    }
    return f;
}

// Branching lightning bolt, top of frame down to yEnd.
void bolt(const Ctx& cx, float x0, float yEnd, unsigned long long salt) {
    std::vector<V2> pts;
    float x = x0;
    for (int i = 0; i <= 10; i++) {
        pts.push_back({ x, yEnd * i / 10.f });
        x += (float)rrange(SEED, salt * 97 + i * 7 + 1, -70, 70);
    }
    dr::polyStroke(cx, pts.data(), (int)pts.size(), false, 10.f, withAlpha(mkColor(0xcfe0ff), 0.20f));
    dr::polyStroke(cx, pts.data(), (int)pts.size(), false, 3.f, withAlpha(mkColor(0xe6eeff), 0.95f));
    for (int b = 0; b < 3; b++) {                       // short branches
        int at = 3 + (int)(rnd01(SEED, salt + b * 13) * 5);
        V2 p = pts[(size_t)at];
        V2 q{ p.x + (float)rrange(SEED, salt + b, -120, 120), p.y + 60 };
        dr::polyStroke(cx, std::vector<V2>{ p, { (p.x + q.x) / 2, (p.y + q.y) / 2 + 10 }, q }.data(), 3,
                       false, 1.6f, withAlpha(mkColor(0xcfe0ff), 0.7f));
    }
}

// Screen-space rain: slanted streaks with wind drift.
void rain(const Ctx& cx, int t, float intensity, float wind = 60.f) {
    if (intensity <= 0.01f) return;
    for (int i = 0; i < 150; i++) {
        V2 p = rvec2(SEED, 500, i);
        float speed = 900 + 500 * p.x;
        float x = (float)std::fmod(p.x * (W + 160) + t * wind, W + 160) - 80;
        float y = (float)std::fmod(p.y * (H + 160) + t * speed, H + 160) - 80;
        float len = 14 + 10 * p.y;
        dr::strokeSeg(cx, { x, y }, { x - wind * 0.03f * len, y + len }, 1.6f,
                      withAlpha(mkColor(0xaab4d8), 0.16f * intensity));
    }
}

void fog(const Ctx& cx, int t, float y0, unsigned long long salt, float alpha) {
    for (int i = 0; i < 7; i++) {
        float x = (float)std::fmod((float)rrange(SEED, salt + i, 0, W) + t * (6 + 5 * i), W + 500) - 250;
        float y = y0 + 16.f * (float)std::sin(t * 0.05 + i);
        dr::blob(cx, { x, y }, 90 + 26.f * (i % 3), 12, 3, i * 57.f + t, withAlpha(mkColor(0x9a8fc0), alpha));
    }
}

// Rising smoke wisps: each puff cycles upward and fades.
void smoke(const Ctx& cx, V2 at, int t, unsigned long long seed, int n, float rise, Color col, float alpha) {
    for (int i = 0; i < n; i++) {
        float ph = (float)rrange(seed, i, 0, 100);
        float u = std::fmod((t + ph * 3.f) / rise, 1.f);
        float x = at.x + (float)std::sin(u * 6.3 + i) * (12 + 30 * u);
        float y = at.y - u * rise;
        dr::circle(cx, { x, y }, 6 + 26 * u, withAlpha(col, alpha * (1 - u)));
    }
}

// Rising embers around a hot presence.
void embers(const Ctx& cx, V2 at, int t, unsigned long long seed, int n, float spread, float rise) {
    for (int i = 0; i < n; i++) {
        float ph = (float)rrange(seed, i, 0, 100);
        float u = std::fmod((t * (2 + 2 * (float)rnd01(seed, i + 50)) + ph * 4) / rise, 1.f);
        float x = at.x + (float)std::sin(u * 9 + i * 1.7) * spread * (0.3f + u);
        float y = at.y + 20 - u * rise;
        float tw = 0.4f + 0.6f * (float)std::sin(t * 0.9 + i);
        dr::circle(cx, { x, y }, 2 + 2.5f * (float)rnd01(seed, i + 90), withAlpha(FLAME, 0.5f * (1 - u) * tw));
    }
}

// ================================================================== props
// Jagged treeline silhouette.
void forest(const Ctx& cx, float baseY, float hMin, float hMax, unsigned long long salt, Color col) {
    std::vector<V2> pts{ { -60, H + 60 } };
    for (int i = 0; i <= 30; i++) {
        float x = -60 + (W + 120) * i / 30.f;
        pts.push_back({ x, baseY - (float)rrange(SEED, salt * 100 + i, hMin, hMax) });
    }
    pts.push_back({ W + 60, H + 60 });
    dr::fillPoly(cx, pts.data(), (int)pts.size(), col);
}

// Old banyan: thick trunk, wide canopy blobs, hanging aerial roots.
void banyan(const Ctx& cx, V2 at, float s, Color col, int t) {
    Vector2 trunk[4] = { { at.x - 26 * s, at.y }, { at.x + 26 * s, at.y },
                         { at.x + 10 * s, at.y - 150 * s }, { at.x - 10 * s, at.y - 150 * s } };
    dr::fillPoly(cx, trunk, 4, col);
    float sway = 3 * (float)std::sin(t * 0.04);
    for (int i = 0; i < 6; i++) {
        float a = -2.6 + 1.05 * i;
        V2 c{ at.x + 110 * s * (float)std::cos(a) + sway, at.y - 175 * s + 34 * s * (float)std::sin(a) };
        dr::blob(cx, c, (52 + 14 * (i % 3)) * s, 10 * s, 5, i * 51.f + t * 0.3f, col);
    }
    for (int i = 0; i < 7; i++) {
        float x = at.x + (-70 + 24 * i) * s;
        dr::strokeSeg(cx, { x, at.y - 140 * s }, { x + sway * (float)std::sin(i), at.y - 10 * s },
                      2.2f * s, col);
    }
}

// Indonesian grave: earthen mound + nisan headstone.
void grave(const Ctx& cx, V2 at, float s, Color mound, Color stone, float crackGlow = 0) {
    Vector2 m[4] = { { at.x - 34 * s, at.y }, { at.x + 34 * s, at.y },
                     { at.x + 20 * s, at.y - 16 * s }, { at.x - 20 * s, at.y - 16 * s } };
    dr::fillPoly(cx, m, 4, mound);
    dr::roundRect(cx, at.x - 6 * s, at.y - 44 * s, 12 * s, 32 * s, 6 * s, stone);
    if (crackGlow > 0.01f) {
        float fl = 0.7f + 0.3f * (float)std::sin(at.x + crackGlow * 9);
        for (int i = 2; i >= 0; i--)
            dr::circle(cx, { at.x, at.y - 4 * s }, (22 + i * 16) * s * crackGlow,
                       withAlpha(DEMIT_RED, 0.16f * fl));
        dr::strokeSeg(cx, { at.x, at.y + 2 * s }, { at.x + 10 * s, at.y - 12 * s }, 2.5f * s,
                      withAlpha(DEMIT_RED, 0.9f * crackGlow));
        dr::strokeSeg(cx, { at.x + 4 * s, at.y - 4 * s }, { at.x - 8 * s, at.y - 20 * s }, 2 * s,
                      withAlpha(DEMIT_RED, 0.8f * crackGlow));
    }
}

void hut(const Ctx& cx, float x, float baseY, float w, float h, Color col, float windowGlow, int t) {
    dr::quad(cx, { x - w * 0.30f, baseY }, { x + w * 0.30f, baseY },
             { x + w * 0.26f, baseY - h * 0.55f }, { x - w * 0.26f, baseY - h * 0.55f }, col);
    Vector2 roof[4] = { { x - w * 0.55f, baseY - h * 0.5f }, { x + w * 0.55f, baseY - h * 0.5f },
                        { x + w * 0.16f, baseY - h * 1.05f }, { x - w * 0.16f, baseY - h * 1.05f } };
    dr::fillPoly(cx, roof, 4, col);
    // stilt legs
    dr::strokeSeg(cx, { x - w * 0.22f, baseY }, { x - w * 0.22f, baseY + h * 0.10f }, 5, col);
    dr::strokeSeg(cx, { x + w * 0.22f, baseY }, { x + w * 0.22f, baseY + h * 0.10f }, 5, col);
    if (windowGlow > 0.01f) {                           // the sick child's window
        float flicker = windowGlow * (0.75f + 0.25f * (float)std::sin(t * 1.7 + x));
        Rectangle win{ x - w * 0.06f, baseY - h * 0.36f, w * 0.12f, h * 0.15f };
        dr::rect(cx, win.x, win.y, win.width, win.height, withAlpha(FLAME, 0.9f * flicker));
        // mother bending over the child, seen through the window
        if (windowGlow > 0.4f) {
            Color ink = mkColor(0x1a0c02);
            float cxp = x + w * 0.005f;
            dr::circle(cx, { cxp + 3, win.y + win.height * 0.42f }, win.height * 0.13f, ink);
            dr::quad(cx, { cxp - 1, win.y + win.height * 0.95f }, { cxp + 8, win.y + win.height * 0.95f },
                     { cxp + 7, win.y + win.height * 0.45f }, { cxp, win.y + win.height * 0.45f }, ink);
            dr::circle(cx, { cxp + 8, win.y + win.height * 0.72f }, win.height * 0.07f, ink);   // child
        }
        for (int i = 2; i >= 0; i--)                    // glow spills onto the ground
            dr::circle(cx, { x, baseY - h * 0.25f }, (30 + i * 26) * windowGlow,
                       withAlpha(FLAME, 0.05f * flicker));
    }
}

void candle(const Ctx& cx, V2 at, int t, unsigned long long salt) {
    dr::rect(cx, at.x - 3, at.y - 12, 6, 12, mkColor(0xd8cfc0));
    float fl = 1 + 0.3f * (float)std::sin(t * 0.7 + (double)salt);
    dr::circle(cx, { at.x, at.y - 16 }, 7 * fl, withAlpha(FLAME, 0.16f));
    dr::circle(cx, { at.x, at.y - 15 }, 3 * fl, FLAME);
}

// Rotating ritual mandala: counter-spinning glyph rings + inner star.
void mandala(const Ctx& cx, V2 at, float r, float a, int t) {
    if (a <= 0.01f) return;
    Color ink = withAlpha(mkColor(0xffd9a0), a);
    dr::ring(cx, at, r, 2.5f, ink);
    dr::ring(cx, at, r * 0.78f, 1.5f, withAlpha(mkColor(0xffd9a0), a * 0.7f));
    for (int ring = 0; ring < 2; ring++) {
        int n = ring == 0 ? 12 : 8;
        float dir = ring == 0 ? 1 : -1;
        for (int i = 0; i < n; i++) {
            double th = 2 * PI * i / n + dir * t * 0.02 * (ring + 1);
            V2 p{ at.x + r * (0.89f - 0.14f * ring) * (float)std::cos(th),
                  at.y + r * (0.89f - 0.14f * ring) * (float)std::sin(th) };
            dr::star(cx, p, 5.5f, 2.2f, 4, (float)(th * 180 / PI), ink);
        }
    }
    dr::star(cx, at, r * 0.24f, r * 0.10f, 3, t * 0.5f, withAlpha(mkColor(0xffd9a0), a * 0.5f));
    for (int i = 2; i >= 0; i--)
        dr::circle(cx, at, r * (1.15f + i * 0.18f), withAlpha(FLAME, a * 0.03f));
}

// ================================================================== characters
// Mbah Séh, the dukun: robe, blangkon, fluttering selendang, staff with orb.
void dukun(const Ctx& cx, V2 at, float s, int t, bool casting, float halo = 1) {
    Color col = DUKUN_COL;
    if (halo > 0) {
        dr::circle(cx, { at.x, at.y - 80 * s }, 150 * s * halo, withAlpha(FLAME, 0.045f));
        dr::circle(cx, { at.x, at.y - 80 * s }, 90 * s * halo, withAlpha(FLAME, 0.06f));
    }
    dr::quad(cx, { at.x - 26 * s, at.y }, { at.x + 26 * s, at.y },
             { at.x + 15 * s, at.y - 80 * s }, { at.x - 15 * s, at.y - 80 * s }, col);   // robe
    float flut = 6 * (float)std::sin(t * 0.15);                                          // selendang
    Vector2 shawl[4] = { { at.x - 12 * s, at.y - 78 * s }, { at.x - 30 * s + flut, at.y - 20 * s },
                         { at.x - 22 * s + flut, at.y - 16 * s }, { at.x - 5 * s, at.y - 66 * s } };
    dr::fillPoly(cx, shawl, 4, mkColor(0x3a2c5e));
    dr::circle(cx, { at.x, at.y - 92 * s }, 13 * s, col);                                // head
    dr::roundRect(cx, at.x - 9 * s, at.y - 113 * s, 18 * s, 9 * s, 3 * s, col);          // blangkon
    dr::strokeSeg(cx, { at.x - 10 * s, at.y - 70 * s }, { at.x - 24 * s, at.y - 52 * s }, 7 * s, col);
    dr::strokeSeg(cx, { at.x - 26 * s, at.y + 2 * s }, { at.x - 26 * s, at.y - 120 * s }, 3.5f * s, col);
    if (casting) {                                                                       // raised arm
        float sw = 4 * (float)std::sin(t * 0.6);
        dr::strokeSeg(cx, { at.x + 10 * s, at.y - 70 * s }, { at.x + 30 * s + sw, at.y - 98 * s }, 7 * s, col);
        dr::circle(cx, { at.x + 30 * s + sw, at.y - 98 * s }, 6 * s, withAlpha(FLAME, 0.25f));
    } else {
        dr::strokeSeg(cx, { at.x + 10 * s, at.y - 70 * s }, { at.x + 24 * s, at.y - 52 * s }, 7 * s, col);
    }
    Color tip = casting ? FLAME : col;
    dr::circle(cx, { at.x - 26 * s, at.y - 124 * s }, 5 * s, tip);
    if (casting) dr::circle(cx, { at.x - 26 * s, at.y - 124 * s }, 12 * s, withAlpha(FLAME, 0.12f));
}

// Villager silhouette: peci/sarong, kneeling or standing.
void villager(const Ctx& cx, V2 at, float s, int t, bool kneeling) {
    Color col = SILHOUETTE;
    float bob = kneeling ? 0 : 1.5f * (float)std::sin(t * 0.2 + at.x);
    if (kneeling) {
        dr::circle(cx, { at.x, at.y - 34 * s + bob }, 9 * s, col);
        dr::quad(cx, { at.x - 14 * s, at.y }, { at.x + 14 * s, at.y },
                 { at.x + 9 * s, at.y - 28 * s }, { at.x - 9 * s, at.y - 28 * s }, col);
        dr::roundRect(cx, at.x - 7 * s, at.y - 46 * s + bob, 14 * s, 5 * s, 2 * s, col);
    } else {
        dr::circle(cx, { at.x, at.y - 92 * s + bob }, 10 * s, col);
        dr::quad(cx, { at.x - 16 * s, at.y }, { at.x + 16 * s, at.y },
                 { at.x + 10 * s, at.y - 78 * s }, { at.x - 10 * s, at.y - 78 * s }, col);
        dr::roundRect(cx, at.x - 8 * s, at.y - 106 * s + bob, 16 * s, 6 * s, 2 * s, col);
    }
}

// Demit Wuluhan, v2: horned shadow with flapping wings, burning eyes, animated maw.
void demit(const Ctx& cx, V2 at, float s, int t, float rage, bool wings = false) {
    float pulse = 1 + 0.05f * (float)std::sin(t * 0.35);
    Color aura = withAlpha(mkColor(0x3a0508), 0.45f + 0.25f * rage);
    if (wings) {                                          // scalloped membrane wings
        float flap = (float)std::sin(t * 0.19);
        for (int side = -1; side <= 1; side += 2) {
            V2 sh{ at.x + side * 30 * s, at.y - 30 * s };
            for (int i = 1; i <= 4; i++) {
                float u = i / 4.f;
                V2 tip{ sh.x + side * 120 * s * u,
                        sh.y - (55 * flap - 30) * s * u - 18 * s * u };
                dr::blob(cx, tip, (42 - 5 * i) * s, 9 * s, 4, i * 43.f + side * 10, aura);
                dr::blob(cx, tip, (32 - 4 * i) * s, 7 * s, 5, i * 31.f, mkColor(0x120307));
            }
        }
    }
    dr::blob(cx, at, 86 * s * pulse, 10 * s, 4, t * 1.7f, aura);
    dr::blob(cx, at, 70 * s * pulse, 8 * s, 5, t * 2.3f + 40, withAlpha(mkColor(0x120307), 0.95f));
    Vector2 hornL[4] = { { at.x - 28 * s, at.y - 42 * s }, { at.x - 40 * s, at.y - 74 * s },
                         { at.x - 50 * s, at.y - 96 * s }, { at.x - 16 * s, at.y - 58 * s } };
    Vector2 hornR[4] = { { at.x + 28 * s, at.y - 42 * s }, { at.x + 40 * s, at.y - 74 * s },
                         { at.x + 50 * s, at.y - 96 * s }, { at.x + 16 * s, at.y - 58 * s } };
    dr::fillPoly(cx, hornL, 4, mkColor(0x1a0409));
    dr::fillPoly(cx, hornR, 4, mkColor(0x1a0409));
    for (int i = 0; i < 4; i++) {
        float r = (16 - 3 * i) * s;
        dr::circle(cx, { at.x - 16 * s, at.y - 18 * s }, r, withAlpha(DEMIT_RED, 0.05f + 0.03f * rage));
        dr::circle(cx, { at.x + 16 * s, at.y - 18 * s }, r, withAlpha(DEMIT_RED, 0.05f + 0.03f * rage));
    }
    float blink = (float)std::clamp(1.0 - std::sin(t * 0.23) * 4.0, 0.0, 1.0);            // eye blink
    dr::circle(cx, { at.x - 16 * s, at.y - 18 * s }, 5 * s, withAlpha(DEMIT_RED, 0.4f + 0.6f * blink));
    dr::circle(cx, { at.x + 16 * s, at.y - 18 * s }, 5 * s, withAlpha(DEMIT_RED, 0.4f + 0.6f * blink));
    float jaw = 3 + 4 * (float)std::sin(t * 0.7);                                         // snapping maw
    Vector2 mouth[8] = { { at.x - 22 * s, at.y + 6 * s }, { at.x - 11 * s, at.y + (6 + jaw) * s },
                         { at.x, at.y + 6 * s },          { at.x + 11 * s, at.y + (6 + jaw) * s },
                         { at.x + 22 * s, at.y + 6 * s }, { at.x + 12 * s, at.y + (16 + jaw) * s },
                         { at.x - 12 * s, at.y + (16 + jaw) * s } };
    dr::fillPoly(cx, mouth, 7, withAlpha(mkColor(0x5c0a08), 0.9f));
}

// ================================================================== camera
struct Cam { Vector2 at{ W / 2, H / 2 }; float zoom = 1; float shake = 0; };
using CamFn = std::function<Cam(int)>;

// World child node: applies the virtual camera (pan + zoom + shake) to world-space drawing.
TNode* world(TNode* scene, CamFn camFn) {
    TNode* n = scene->add(0, scene->dur);
    n->up = [camFn](int t, NodeProps& p) {
        Cam c = camFn(t);
        float sx = 0, sy = 0;
        if (c.shake > 0.01f) {
            sx = (float)rrange(SEED, (unsigned long long)t * 17 + 1, -c.shake, c.shake);
            sy = (float)rrange(SEED, (unsigned long long)t * 17 + 2, -c.shake, c.shake);
        }
        p.scale = c.zoom;
        p.pos = { W / 2 - c.at.x * c.zoom + sx, H / 2 - c.at.y * c.zoom + sy };
    };
    return n;
}

TNode* fx(TNode* scene, std::function<void(const Ctx&, int)> f) {
    TNode* n = scene->add(0, scene->dur);
    n->fn = std::move(f);
    return n;
}

void caption(const Ctx& cx, const std::string& s, float y, float a, float size = 30) {
    if (a <= 0.005f) return;
    TextStyle st;
    st.font = fonts::ui(false);
    st.size = size;
    st.color = withAlpha(BONE, a);
    st.align = Align::Center;
    st.valign = Align::Center;
    dr::textBox(cx, s, { 90, y, W - 180, size * 2.6f }, st);
}

// caption alpha over a lifetime window: fade in [in0,in1], hold, fade out [out0,out1]
float capA(double t, double in0, double in1, double out0, double out1) {
    return (float)interpolate(t, { in0, in1, out0, out1 }, { 0, 1, 1, 0 }, clamped());
}

// night sky with stars, blood moon, dawn blend and flash brightening
void nightSky(const Ctx& cx, int t, float flash, float dawn = 0) {
    Color top = mixC(mixC(NIGHT_TOP, mkColor(0x3a4668), flash * 0.7), mkColor(0x2c4a7a), dawn);
    Color bot = mixC(mixC(NIGHT_BOT, mkColor(0x54425e), flash * 0.5), mkColor(0xff9a52), dawn);
    dr::rectGrad4(cx, 0, 0, W, H, top, top, bot, bot);
    for (int i = 0; i < 110; i++) {
        V2 p = rvec2(SEED, 3, i);
        float tw = 0.5f + 0.5f * (float)std::sin(t * 0.13 + i * 1.71);
        dr::rect(cx, p.x * W, p.y * H * 0.55f, 2.4f, 2.4f,
                 withAlpha(mkColor(0xdfe8ff), (0.18f + 0.55f * tw) * (1 - flash) * (1 - dawn)));
    }
    V2 m{ W * 0.79f, H * 0.20f };
    for (int i = 5; i >= 1; i--) dr::circle(cx, m, 34.f + 16 * i, withAlpha(MOON_RED, 0.03f * (1 - dawn)));
    dr::circle(cx, m, 34, mixC(mkColor(0xf0eaff), MOON_RED, 0.55f * (1 - dawn)));
    dr::circle(cx, { m.x - 10, m.y - 6 }, 7, withAlpha(mkColor(0x9a90c8), 0.5f * (1 - dawn)));
    dr::circle(cx, { m.x + 8, m.y + 9 }, 5, withAlpha(mkColor(0x9a90c8), 0.4f * (1 - dawn)));
}

// film grain + vignette + letterbox, over everything
void grainVignette(const Ctx& cx, int t) {
    dr::ring(cx, { W / 2, H / 2 }, H * 1.02f, H * 0.45f, mkColor(0, 55));
    dr::rect(cx, 0, 0, W, H * 0.055f, BLACK);                     // letterbox
    dr::rect(cx, 0, H - H * 0.055f, W, H * 0.055f, BLACK);
    for (int i = 0; i < 260; i++) {
        V2 p = rvec2(SEED, 9000 + (t % 2) * 7, i);
        float v = (float)rnd01(SEED, 7000 + i + t * 131);
        dr::rect(cx, p.x * W, p.y * (H - H * 0.11f) + H * 0.055f, 2, 2,
                 v > 0.5f ? Color{ 255, 255, 255, 14 } : Color{ 0, 0, 0, 20 });
    }
}

// =================================================================-- generated audio (rain, wind, screech)
bool audioReady = false;

void ensureAudio() {
    if (audioReady) return;
    audioReady = true;
    std::error_code ec;
    std::filesystem::create_directories(AUDIO_DIR, ec);
    const int rate = 22050;

    // rain: dense filtered noise with droplet patter
    if (!std::filesystem::exists(AUDIO_DIR + "/rain.wav")) {
        std::vector<float> s((size_t)rate * 20);
        double lp = 0;
        unsigned long long st = 1;
        for (size_t i = 0; i < s.size(); i++) {
            double n = rnd01(st, i) * 2 - 1;
            lp += 0.28 * (n - lp);                                       // hiss layer
            double pat = 0;                                              // droplet patter
            unsigned long long k = i / 700;
            if (rnd01(7, k + i % 700 * 0) < 0.002) pat = (rnd01(9, i) * 2 - 1) * std::exp(-(double)(i % 700) / 60);
            s[i] = (float)(0.30 * lp + 0.16 * pat);
        }
        writeWavMono(AUDIO_DIR + "/rain.wav", rate, s);
    }
    // wind: slowly swelling low rumble
    if (!std::filesystem::exists(AUDIO_DIR + "/wind.wav")) {
        std::vector<float> s((size_t)rate * 20);
        double lp1 = 0, lp2 = 0;
        for (size_t i = 0; i < s.size(); i++) {
            double n = rnd01(11, i) * 2 - 1;
            lp1 += 0.02 * (n - lp1);
            lp2 += 0.004 * (lp1 - lp2);
            double swell = 0.6 + 0.4 * std::sin(2 * PI * i / (rate * 7.3));
            s[i] = (float)(2.4 * lp2 * swell);
        }
        writeWavMono(AUDIO_DIR + "/wind.wav", rate, s);
    }
    // screech: descending ring-modulated squeal, 1.6 s
    if (!std::filesystem::exists(AUDIO_DIR + "/screech.wav")) {
        std::vector<float> s((size_t)(rate * 1.6));
        for (size_t i = 0; i < s.size(); i++) {
            double u = (double)i / s.size();
            double f = 1500 - 950 * u + 60 * std::sin(u * 50);
            double env = std::min(u / 0.06, 1.0) * std::exp(-2.2 * u);
            double v = std::sin(2 * PI * f * i / rate) *
                       (0.6 + 0.4 * std::sin(2 * PI * 83 * i / rate));
            s[i] = (float)(0.5 * env * v + 0.10 * env * (rnd01(13, i) * 2 - 1));
        }
        writeWavMono(AUDIO_DIR + "/screech.wav", rate, s);
    }
}

// =================================================================-- the film
void registerComps(Registry& out) {
    Comp c;
    c.name = "dukun-vs-demit";
    c.w = (int)W; c.h = (int)H; c.fps = FPS;
    c.background = NIGHT_TOP;
    c.music = true;
    c.supersample = 2;
    c.assets = [](const Comp&, const Json&) { ensureAudio(); };

    TransitionSeries ts(c.roots, W, H);
    std::vector<int> sceneStart;
    auto scene = [&](int dur, std::function<void(const Ctx&, int)> fn) {
        sceneStart.push_back(ts.end());
        TNode* n = ts.add(dur);
        n->fn = std::move(fn);
        return n;
    };
    auto fade = [](TNode* n, int dur, int inF = 12, int outF = 14) {
        n->up = [dur, inF, outF](int t, NodeProps& p) {
            p.opacity = (float)interpolate(t, { 0.0, (double)inF, (double)(dur - outF), (double)dur },
                                           { 0, 1, 1, 0 }, clamped());
        };
    };


    // ---- SHOT 1 -- cold open: storm over the banyan graveyard (14 s) --------
    {
        TNode* n = scene(420, [](const Ctx& cx, int t) {
            float flash = flashAt(t, 5);
            Cam cam{ { W * 0.5f + 60 * (float)std::sin(t * 0.008), H * 0.5f }, 1.15f + t * 0.0006f, 0 };
            nightSky(cx, t, flash);
            float parx = (cam.at.x - W / 2) * 0.4f;                    // far layer drifts less
            Ctx bg = cx; bg.o.x -= parx;
            forest(bg, H * 0.86f, 40, 110, 1, mixC(SILHOUETTE, NIGHT_TOP, 0.35f));
            if (flash > 0.4f) bolt(bg, W * 0.32f, H * 0.55f, t / 2);
            Ctx near_ = cx; near_.o.x += (cam.at.x - W / 2) * 0.6f;
            banyan(near_, { W * 0.30f, H * 0.88f }, 1.25f, SILHOUETTE, t);
            grave(near_, { W * 0.62f, H * 0.90f }, 1.2f, mkColor(0x0c0716), mkColor(0x120a1c));
            grave(near_, { W * 0.78f, H * 0.93f }, 1.0f, mkColor(0x0c0716), mkColor(0x120a1c));
            fog(near_, t, H * 0.84f, 11, 0.07f);
            rain(cx, t, std::min(1.f, t / 60.f));
            float a1 = capA(t, 30, 46, 150, 175);
            caption(cx, "Kampung Wanara, 1974.", H * 0.70f, a1);
            float a2 = capA(t, 220, 240, 380, 405);
            caption(cx, "Malam itu, hujan tidak turun sendirian.", H * 0.70f, a2);
        });
        fade(n, 420, 6, 22);
    }

    // ---- SHOT 2 -- the grave breaks open (16 s) -----------------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(480, [](const Ctx& cx, int t) {
            float flash = flashAt(t, 9);
            nightSky(cx, t, flash);
            forest(cx, H * 0.88f, 50, 120, 2, SILHOUETTE);
            float open = (float)interpolate(t, { 90.0, 240.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::cubic)));
            float shake = open * 2.2f;
            Ctx j = cx;
            j.o.x += (float)rrange(SEED, (unsigned long long)t * 19 + 1, -shake, shake);
            j.o.y += (float)rrange(SEED, (unsigned long long)t * 19 + 2, -shake, shake);
            grave(j, { W * 0.50f, H * 0.86f }, 1.6f, mkColor(0x0c0716), mkColor(0x120a1c), open);
            grave(j, { W * 0.24f, H * 0.89f }, 1.0f, mkColor(0x0c0716), mkColor(0x120a1c));
            banyan(j, { W * 0.82f, H * 0.90f }, 1.1f, SILHOUETTE, t);
            fog(j, t, H * 0.86f, 12, 0.07f);
            // the demit claws its way out of the mound
            if (t > 240) {
                float rise = (float)interpolate(t, { 240.0, 330.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
                smoke(j, { W * 0.50f, H * 0.78f }, t, 60, 10, 60.f, mkColor(0x2a040a), 0.4f);
                demit(j, { W * 0.50f, H * 0.74f - 120 * rise }, 0.35f + 0.55f * rise, t, rise);
                if (t == 300 || t == 301) {} // (screech audio is attached below)
            }
            if (flash > 0.5f) bolt(j, W * 0.5f, H * 0.45f, 3 + t / 3);
            rain(cx, t, 1);
            float a = capA(t, 380, 398, 442, 462);
            caption(cx, "Tanah kubur Wuluhan pecah.", H * 0.70f, a, 32);
        });
        fade(n, 480);
    }

    // ---- SHOT 3 -- title sequence (12 s) ------------------------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(360, [](const Ctx& cx, int t) {
            float flash = flashAt(t, 13);
            nightSky(cx, t, flash);
            forest(cx, H * 0.80f, 40, 120, 3, SILHOUETTE);
            fog(cx, t, H * 0.75f, 14, 0.06f);
            if (flash > 0.45f) bolt(cx, W * 0.30f, H * 0.62f, t / 2);
            float fl = 1 + 0.25f * (float)std::sin(t * 0.9);
            V2 p{ W * 0.14f, H * 0.72f };
            dr::rect(cx, p.x - 4, p.y - 66, 8, 22, mkColor(0x2a1c10));
            dr::circle(cx, { p.x, p.y - 30 }, 22 * fl, withAlpha(FLAME, 0.15f));
            dr::blob(cx, { p.x, p.y - 30 }, 24, 3, 8, 0, mkColor(0xd96a1e));
            Vector2 eyes[3] = { { p.x - 10, p.y - 34 }, { p.x - 4, p.y - 42 }, { p.x + 2, p.y - 34 } };
            dr::fillPoly(cx, eyes, 3, mkColor(0x1a0c02));
            Vector2 eyes2[3] = { { p.x + 3, p.y - 34 }, { p.x + 9, p.y - 42 }, { p.x + 15, p.y - 34 } };
            dr::fillPoly(cx, eyes2, 3, mkColor(0x1a0c02));
            Vector2 grin[4] = { { p.x - 12, p.y - 24 }, { p.x + 12, p.y - 24 },
                                { p.x + 8, p.y - 18 }, { p.x - 8, p.y - 18 } };
            dr::fillPoly(cx, grin, 4, mkColor(0x1a0c02));
            float a = (float)interpolate(t, { 8.0, 26.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            TextStyle big;
            big.font = fonts::ui(true); big.size = 118; big.align = Align::Center;
            TextStyle vs = big; vs.size = 54; vs.color = withAlpha(DEMIT_RED, a);
            big.color = withAlpha(BONE, a);
            dr::textBox(cx, "DUKUN", { 140, H * 0.30f, W - 280, 140 }, big);
            dr::textBox(cx, "vs  DEMIT", { 140, H * 0.435f, W - 280, 80 }, vs);
            TextStyle sub;
            sub.font = fonts::ui(false); sub.size = 28; sub.align = Align::Center;
            sub.color = withAlpha(mkColor(0xb8a8d8), 0.9f * a);
            dr::textBox(cx, "sebuah film horor prosedural \xC2\xB7 setiap piksel dan nada dibuat oleh kode",
                        { 140, H * 0.55f, W - 280, 60 }, sub);
        });
        fade(n, 360, 8, 20);
    }

    // ---- SHOT 4 -- the village, panic begins (18 s) -------------------------
    ts.transition(Transition::slide(TR, Direction::FromRight));
    {
        TNode* n = scene(540, [](const Ctx& cx, int t) {
            Cam cam{ { 200 + 880 * (float)interpolate(t, { 20.0, 470.0 }, { 0.0, 1.0 },
                                    clamped(ease::inOut(ease::sine))), H * 0.52f }, 1.0f, 0 };
            float parx = (cam.at.x - W / 2) * 0.35f;
            nightSky(cx, t, flashAt(t, 17));
            Ctx bg = cx; bg.o.x -= parx;
            forest(bg, H * 0.84f, 60, 150, 4, mixC(SILHOUETTE, NIGHT_TOP, 0.3f));
            // world-space huts: the sick child's hut is the second one
            Ctx j = cx;
            j.o.x -= (cam.at.x - W / 2) * 1.0f;
            hut(j, 260,  H * 0.94f, 300, 200, mkColor(0x0c0716), 0, t);
            hut(j, 700,  H * 0.96f, 360, 230, mkColor(0x0a0513), 1, t);
            hut(j, 1140, H * 0.94f, 320, 210, mkColor(0x0c0716), 0, t);
            fog(j, t, H * 0.97f, 15, 0.04f);
            // villagers running between the huts, torches up
            for (int i = 0; i < 4; i++) {
                float u = std::fmod(t * 0.012 + i * 0.31f, 1.f);
                float x = 120 + u * 1000;
                float y = H * (0.90f + 0.03f * (float)std::sin(i * 2.1));
                villager(j, { x, y }, 1.05f, t, false);
                dr::strokeSeg(j, { x + 14, y - 74 }, { x + 20, y - 96 }, 3, SILHOUETTE);
                dr::circle(j, { x + 20, y - 100 }, 6, withAlpha(FLAME, 0.9f));
                dr::circle(j, { x + 20, y - 100 }, 14, withAlpha(FLAME, 0.12f));
            }
            // the demit's shadow slides across the roof, late in the shot
            float sh = (float)interpolate(t, { 380.0, 520.0 }, { 0.0, 1.0 }, clamped());
            if (sh > 0.01f) demit(j, { 260 + 700 * sh, H * 0.52f }, 0.55f, t, sh * 0.6f, true);
            rain(cx, t, 0.4f);
            float a1 = capA(t, 24, 44, 130, 155);
            caption(cx, "Anak di kampung itu sakit satu per satu. Malam ini, gilirannya datang.",
                    H * 0.72f, a1);
            float a2 = capA(t, 300, 320, 500, 525);
            caption(cx, "Dan sesuatu telah mulai berkeliaran di atas atap.", H * 0.72f, a2);
        });
        fade(n, 540);
    }

    // ---- SHOT 5 -- the summons: Mbah Séh arrives (18 s) ---------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(540, [](const Ctx& cx, int t) {
            Cam cam{ { W * 0.5f, H * 0.55f }, 1.08f + 0.10f * (float)interpolate(t, { 0.0, 540.0 }, { 0.0, 1.0 },
                                     clamped(ease::inOut(ease::sine))), 0 };
            nightSky(cx, t, flashAt(t, 21));
            forest(cx, H * 0.82f, 50, 130, 5, SILHOUETTE);
            fog(cx, t, H * 0.80f, 16, 0.09f);
            // villagers kneeling in a half-circle, torches planted
            for (int i = 0; i < 7; i++) {
                float x = W * 0.18f + i * W * 0.105f;
                if (i == 3) continue;
                villager(cx, { x, H * 0.90f - 20 * (float)std::sin(i * 0.9) }, 1.0f, t, true);
            }
            for (int i = 0; i < 3; i++)
                candle(cx, { W * 0.30f + i * W * 0.20f, H * 0.915f }, t, i + 30);
            // the dukun walks in from the fog
            float walk = (float)interpolate(t, { 40.0, 260.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            float x = W * 0.92f - (W * 0.42f) * walk;
            dukun(cx, { x, H * 0.88f }, 1.15f, t, false);
            fog(cx, t + 120, H * 0.86f, 17, 0.10f);            // second fog bank he parts
            float a = capA(t, 60, 84, 480, 512);
            caption(cx, "Mereka memanggil satu-satunya orang yang berani datang: Mbah S\xC3\xA9h.",
                    H * 0.72f, a);
        });
        fade(n, 540);
    }

    // ---- SHOT 6 -- the ritual: mandala + chanting montage (20 s) ------------
    ts.transition(Transition::wipe(TR, Direction::FromLeft));
    {
        TNode* n = scene(600, [](const Ctx& cx, int t) {
            nightSky(cx, t, 0);
            forest(cx, H * 0.84f, 50, 130, 6, SILHOUETTE);
            fog(cx, t, H * 0.84f, 18, 0.07f);
            // candle circle
            for (int i = 0; i < 12; i++) {
                double th = 2 * PI * i / 12.0;
                candle(cx, { W * 0.42f + 170 * (float)std::cos(th),
                             H * 0.87f - 55 * (float)std::sin(th) }, t, i + 40);
            }
            smoke(cx, { W * 0.42f, H * 0.85f }, t, 70, 6, 95.f, mkColor(0x8a7fb0), 0.11f);
            float mand = (float)interpolate(t, { 30.0, 90.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            mandala(cx, { W * 0.42f, H * 0.62f }, 150.f, mand * 0.9f, t);
            dukun(cx, { W * 0.42f, H * 0.87f }, 1.25f, t, true, 1.2f);
            // villagers kneel behind him
            for (int i = 0; i < 3; i++) villager(cx, { W * 0.78f + i * 60, H * 0.90f }, 0.9f, t, true);
            rain(cx, t, (float)interpolate(t, { 430.0, 520.0 }, { 0.0, 0.8f }, clamped()));
            float a1 = capA(t, 20, 40, 150, 180);
            caption(cx, "\"Huuuu... angker mulang... kula dhawuhi...\"", H * 0.72f, a1, 30);
            float a2 = capA(t, 190, 210, 330, 360);
            caption(cx, "\"Demi asma tertinggi, kembalilah ke tanahmu!\"", H * 0.72f, a2, 30);
            float a3 = capA(t, 370, 390, 560, 585);
            caption(cx, "Kemenyan mengepul. Lingkaran api siap. Hujan mulai turun.", H * 0.72f, a3);
        });
        fade(n, 600);
    }

    // ---- SHOT 7 -- the possession: the window dies (14 s) -------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(420, [](const Ctx& cx, int t) {
            float die = (float)interpolate(t, { 60.0, 200.0 }, { 1.0, 0.0 }, clamped(ease::inOut(ease::quad)));
            float rage = (float)interpolate(t, { 100.0, 300.0 }, { 0.0, 1.0 }, clamped());
            Cam cam{ { W * 0.55f, H * 0.55f }, 1.25f, rage * 2.5f };
            nightSky(cx, t, 0);
            forest(cx, H * 0.86f, 60, 140, 7, SILHOUETTE);
            fog(cx, t, H * 0.86f, 19, 0.08f);
            hut(cx, 420, H * 0.95f, 430, 250, mkColor(0x0a0513), die, t);
            // crawling shadow over the roof
            float crawl = (float)interpolate(t, { 120.0, 330.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::quad)));
            if (crawl > 0.01f) {
                Ctx sh = cx;
                sh.a *= 0.85f * crawl;
                demit(sh, { 420 - 200 + 560 * crawl, H * 0.56f }, 0.5f + 0.35f * crawl, t, rage, true);
            }
            embers(cx, { 420, H * 0.62f }, t, 80, 10, 130.f, 150.f);
            rain(cx, t, 1);
            float a = capA(t, 150, 172, 380, 405);
            caption(cx, "Demit Wuluhan marah. Cahaya itu... dipadamkan.", H * 0.70f, a, 32);
        });
        fade(n, 420);
    }

    // ---- SHOT 8 -- the duel (22 s) ------------------------------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(660, [](const Ctx& cx, int t) {
            // choreography: circle (0-160), lunge 1 (160-230), lunge 2 (260-330),
            // lunge 3 (360-430), kneel + staff (430-530), beam (530-660)
            float phase = t;
            float shake = 0;
            if (phase > 160 && phase < 430) shake = 3 + 2 * (float)std::sin(phase * 0.3);
            if (phase > 530) shake = (float)interpolate(phase, { 530.0, 560.0, 640.0, 660.0 },
                                                        { 0.0, 8.0, 8.0, 0.0 }, clamped());
            Cam cam{ { W * 0.5f, H * 0.52f }, 1.0f, shake };
            nightSky(cx, t, flashAt(t, 25), 0);
            forest(cx, H * 0.88f, 60, 150, 8, SILHOUETTE);
            fog(cx, t, H * 0.86f, 20, 0.07f);

            // dukun: stands, then kneels, then plants the staff
            float kneel = (float)interpolate(t, { 430.0, 470.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::quad)));
            dukun(cx, { W * 0.26f, H * 0.90f - 30 * kneel }, 1.3f - 0.1f * kneel, t, true, 1 + kneel);

            // mandala grows from him during the kneel
            float mand = (float)interpolate(t, { 450.0, 560.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            mandala(cx, { W * 0.26f, H * 0.66f }, 40 + 150 * mand, mand, t);

            // demit: enters flying, circles, lunges thrice
            float dx = W * 0.74f, dy = H * 0.45f, ds = 1.05f;
            if (t < 160) {
                float in = (float)interpolate(t, { 0.0, 120.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
                dx = W * 0.90f - W * 0.16f * in;
                dy = H * 0.16f + H * 0.29f * in;
            } else if (t < 430) {
                double a = t * 0.045;
                dx = W * 0.60f + W * 0.14f * (float)std::cos(a);
                dy = H * 0.45f + H * 0.13f * (float)std::sin(a);
                for (double l : { 195.0, 295.0, 395.0 }) {          // lunge toward the dukun
                    double d = t - l;
                    if (d > 0 && d < 35) {
                        float k = (float)std::sin(d / 35 * PI);
                        dx -= 220 * k;
                        dy += 60 * k;
                        ds = 1.05f + 0.25f * k;
                    }
                }
            } else {                                                 // recoils from the beam
                float recoil = (float)interpolate(t, { 540.0, 660.0 }, { 0.0, 1.0 }, clamped());
                dx = W * 0.72f + 60 * recoil;
                dy = H * 0.42f - 30 * recoil + 14 * (float)std::sin(t * 0.5) * recoil;
                ds = 1.05f - 0.2f * recoil;
            }
            demit(cx, { dx, dy }, ds, t, 1, t < 430);

            // protective ring-waves while they clash
            if (t > 100 && t < 530)
                for (int k = 0; k < 3; k++) {
                    float r = (float)std::fmod(t * 3.2 + k * 46.f, 140.f);
                    dr::ring(cx, { W * 0.26f, H * 0.66f }, 60 + r * 2.4f, 3.5f,
                             withAlpha(mkColor(0xffd9a0), 0.5f * (1 - r / 140.f)));
                }
            // the staff is planted: pillar of light
            float beam = (float)interpolate(t, { 530.0, 570.0, 640.0, 660.0 }, { 0.0, 1.0, 1.0, 0.0 }, clamped());
            if (beam > 0.01f) {
                Vector2 col[4] = { { W * 0.26f - 14, -60 }, { W * 0.26f + 14, -60 },
                                   { W * 0.26f + 34, H * 0.90f }, { W * 0.26f - 34, H * 0.90f } };
                dr::fillPoly(cx, col, 4, withAlpha(mkColor(0xfff2d8), 0.55f * beam));
                dr::circle(cx, { W * 0.26f, H * 0.66f }, 90 * beam, withAlpha(mkColor(0xfff2d8), 0.4f * beam));
                dr::rect(cx, -40, -40, W + 80, H + 80, withAlpha(mkColor(0xfff2d8), 0.25f * beam));
            }
            embers(cx, { W * 0.26f, H * 0.66f }, t, 90, 8, 100.f, 130.f);
            rain(cx, t, 0.8f);
            float a = capA(t, 30, 55, 150, 180);
            caption(cx, "\"Asma Bismillah! Kembalilah ke alam gaib, demit!\"", H * 0.70f, a, 32);
        });
        fade(n, 660);
    }

    // ---- SHOT 9 -- the banishment vortex (18 s) ------------------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(540, [](const Ctx& cx, int t) {
            float suck = (float)interpolate(t, { 40.0, 430.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::cubic)));
            float shake = (float)interpolate(t, { 0.0, 80.0, 380.0, 430.0 }, { 0.0, 5.0, 5.0, 0.0 }, clamped());
            Cam cam{ { W * 0.5f, H * 0.55f }, 1.05f, shake };
            nightSky(cx, t, 0);
            forest(cx, H * 0.88f, 60, 150, 9, SILHOUETTE);
            V2 pit{ W * 0.62f, H * 0.84f };
            // the vortex: spiralling particles pulled into the grave mouth
            for (int i = 0; i < 40; i++) {
                float ph = (float)rrange(SEED, 400 + i, 0, 100);
                float u = std::fmod(t * 0.02f + ph / 100.f, 1.f);
                double a = u * 9 + i;
                float r = (1 - u) * 300 * (0.4f + 0.6f * suck);
                dr::circle(cx, { pit.x + r * (float)std::cos(a), pit.y - r * 0.35f * (float)std::sin(a) },
                           2 + 3 * u, withAlpha(mkColor(0x5c1010), 0.5f * (1 - u * 0.4f)));
            }
            dr::blob(cx, pit, 60 * suck, 6, 5, t, withAlpha(mkColor(0x1a0409), 0.95f));
            demit(cx, { pit.x, pit.y - 90 * (1 - suck) }, 1.05f * (1 - 0.65f * suck), t, 1, t < 300);
            smoke(cx, pit, t, 95, 10, 50.f, mkColor(0x2a040a), 0.35f);
            dukun(cx, { W * 0.24f, H * 0.90f }, 1.3f, t, false, 1.3f);
            fog(cx, t, H * 0.86f, 21, 0.07f);
            rain(cx, t, (float)interpolate(t, { 300.0, 470.0 }, { 0.6f, 0.0 }, clamped()));
            float a = capA(t, 60, 84, 480, 512);
            caption(cx, "Sesungguhnya di situlah ia berasal. Ke sanalah ia dikembalikan.",
                    H * 0.70f, a);
        });
        fade(n, 540);
    }

    // ---- SHOT 10 -- aftermath: the window glows again (14 s) -----------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(420, [](const Ctx& cx, int t) {
            float warm = (float)interpolate(t, { 30.0, 120.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            nightSky(cx, t, 0);
            forest(cx, H * 0.86f, 60, 140, 10, SILHOUETTE);
            fog(cx, t, H * 0.86f, 22, 0.05f);
            hut(cx, 420, H * 0.95f, 430, 250, mkColor(0x0a0513), warm, t);
            hut(cx, 900, H * 0.93f, 320, 210, mkColor(0x0c0716), 0.6f, t);
            // villagers emerge, relieved
            for (int i = 0; i < 4; i++) {
                float out = (float)interpolate(t, { 90.0 + i * 30.0, 200.0 + i * 30.0 }, { 0.0, 1.0 }, clamped());
                villager(cx, { 640.f + i * 70, H * 0.94f + 40 * (1 - out) }, 0.95f, t, out < 0.5f);
            }
            dukun(cx, { W * 0.80f - 260 * (float)interpolate(t, { 120.0, 400.0 }, { 0.0, 1.0 },
                                    clamped(ease::inOut(ease::quad))), H * 0.92f }, 1.2f, t, false, 1.1f);
            float a = capA(t, 60, 84, 380, 405);
            caption(cx, "Fajar menjelang. Anak itu bernapas lagi. Kampung menunduk, berterima kasih.",
                    H * 0.70f, a);
        });
        fade(n, 420);
    }

    // ---- SHOT 11 -- dawn... and the twist (14 s) ------------------------------
    ts.transition(Transition::wipe(TR, Direction::FromTop));
    {
        TNode* n = scene(420, [](const Ctx& cx, int t) {
            float dawn = (float)interpolate(t, { 15.0, 110.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::sine)));
            nightSky(cx, t, 0, dawn);
            forest(cx, H * 0.84f, 60, 150, 11, mixC(SILHOUETTE, mkColor(0x30201e), dawn * 0.8f));
            fog(cx, t, H * 0.80f, 23, 0.05f * (1 - dawn));
            banyan(cx, { W * 0.80f, H * 0.88f }, 1.2f, mixC(SILHOUETTE, mkColor(0x2a1a18), dawn * 0.8f), t);
            grave(cx, { W * 0.30f, H * 0.90f }, 1.3f,
                  mixC(mkColor(0x0c0716), mkColor(0x3a2418), dawn), mkColor(0x120a1c));
            grave(cx, { W * 0.48f, H * 0.92f }, 1.0f,
                  mixC(mkColor(0x0c0716), mkColor(0x3a2418), dawn), mkColor(0x120a1c));
            dukun(cx, { W * 0.14f, H * 0.90f }, 1.25f, t, false, 0.8f);
            // ...the twist: an eye reopens in the grave
            float eye = (float)interpolate(t, { 250.0, 285.0, 330.0, 375.0 }, { 0.0, 1.0, 1.0, 0.6f }, clamped());
            if (eye > 0.01f) {
                for (int i = 3; i >= 0; i--)
                    dr::circle(cx, { W * 0.30f, H * 0.855f }, (5 + i * 5), withAlpha(DEMIT_RED, 0.06f * eye));
                dr::circle(cx, { W * 0.30f, H * 0.855f }, 4, withAlpha(DEMIT_RED, 0.9f * eye));
            }
            float a = capA(t, 40, 62, 300, 330);
            caption(cx, "Fajar menyingsing. Kampung aman kembali.", H * 0.70f, a);
            float a2 = capA(t, 300, 322, 390, 412);
            caption(cx, "...tapi tanah kubur tidak pernah diam untuk lama.", H * 0.70f, a2, 32);
        });
        fade(n, 420, 4, 16);
    }

    // ---- SHOT 12 -- credits (15 s) --------------------------------------------
    ts.transition(Transition::fade(TR));
    {
        TNode* n = scene(450, [](const Ctx& cx, int t) {
            float dawn = (float)interpolate(t, { 0.0, 60.0 }, { 0.4f, 0.9f }, clamped());
            nightSky(cx, t, 0, dawn);
            forest(cx, H * 0.84f, 60, 150, 12, mixC(SILHOUETTE, mkColor(0x30201e), dawn * 0.8f));
            TextStyle tamat;
            tamat.font = fonts::ui(true); tamat.size = 96; tamat.align = Align::Center;
            tamat.color = withAlpha(BONE, (float)interpolate(t, { 20.0, 45.0 }, { 0.0, 1.0 }, clamped()));
            dr::textBox(cx, "TAMAT", { 140, H * 0.30f, W - 280, 130 }, tamat);
            TextStyle cred;
            cred.font = fonts::ui(false); cred.size = 26; cred.align = Align::Center;
            cred.color = withAlpha(mkColor(0xcabfe0), 0.9f);
            float roll = (float)interpolate(t, { 60.0, 430.0 }, { 0.0, 1.0 }, clamped(ease::linear));
            auto line = [&](const char* role, const char* name, double at) {
                float a = (float)interpolate(roll, { at, at + 0.08, at + 0.17, at + 0.25 }, { 0, 1, 1, 0 }, clamped());
                if (a <= 0.01f) return;
                cred.color = withAlpha(mkColor(0xcabfe0), a * 0.75f);
                dr::textBox(cx, role, { 140, H * 0.48f - 30 * (1 - a), W - 280, 40 }, cred);
                cred.color = withAlpha(BONE, a);
                dr::textBox(cx, name, { 140, H * 0.48f + 8 - 30 * (1 - a), W - 280, 40 }, cred);
            };
            line("SUTRADARA", "rmtn::TransitionSeries", 0.02);
            line("SKENARIO", "storyboard.cpp", 0.27);
            line("MUSIK & SUARA", "rmtn::synth + writeWavMono", 0.52);
            line("PAMAIN", "Mbah S\xC3\xA9h, Demit Wuluhan, warga Kampung Wanara", 0.77);
        });
        fade(n, 450, 4, 20);
    }

    // weather + grade + letterbox/grain over everything
    TNode* overlay = addRoot(c.roots, 0, ts.end());
    overlay->fn = [](const Ctx& cx, int t) { grainVignette(cx, t); };

    c.duration = ts.end();

    // ---------------------------------------------------------------- audio
    // generated ambience: wind for the whole night, rain until the storm ends
    int stormEnd = sceneStart[9] + 200;                    // rain tapers off in shot 10
    AudioClip& wind = media::audio(addRoot(c.roots, 0, c.duration), AUDIO_DIR + "/wind.wav");
    wind.loop = true; wind.volume = 0.9f;
    wind.volumeAt = [end = c.duration](int t) {
        return (float)interpolate(t, { 0.0, 90.0, (double)end - 400, (double)end }, { 0.0, 1.0, 1.0, 0.0 }, clamped());
    };
    AudioClip& rainClip = media::audio(addRoot(c.roots, 0, stormEnd), AUDIO_DIR + "/rain.wav");
    rainClip.loop = true; rainClip.volume = 1.0f;
    rainClip.volumeAt = [stormEnd](int t) {
        return (float)interpolate(t, { 0.0, 120.0, (double)stormEnd - 150, (double)stormEnd },
                                  { 0.0, 1.0, 1.0, 0.0 }, clamped()) * 0.75f;
    };
    // demit screeches at key story beats (absolute frames)
    std::vector<int> screeches;
    screeches.insert(screeches.end(), { sceneStart[1] + 300, sceneStart[3] + 400, sceneStart[6] + 300,
                                        sceneStart[7] + 195, sceneStart[7] + 295, sceneStart[7] + 395,
                                        sceneStart[7] + 540, sceneStart[8] + 120 });
    for (int f : screeches) {
        if (f + 48 >= c.duration) continue;
        AudioClip& sc = media::audio(addRoot(c.roots, f, 48), AUDIO_DIR + "/screech.wav");
        sc.volume = 0.55f;
    }

    // ---------------------------------------------------------------- score
    Song& s = c.song;
    std::vector<double> sec;
    for (int f : sceneStart) sec.push_back((double)f / FPS);
    double endSec = (double)c.duration / FPS;

    for (double t = 0; t < endSec - 1; t += 3.9)           // uneasy drone vs its tritone
        s.push_back({ t, 4.2, ((long long)(t / 3.9) % 2) ? 77.78 : 55.0, 0.12, false });
    for (size_t i = 1; i < sec.size(); i++)                // sting when each shot lands
        for (int k = 0; k < 3; k++)
            s.push_back({ sec[i] + k * 0.04, 0.5, 587.33 * (1 + 0.07 * k), 0.08, true });
    for (double off : { 0.4, 4.3, 8.9, 26.0, 33.5 })       // distant thunder in act 1
        s.push_back({ sec[0] + off, 1.1, 40.0, 0.45, true });
    double minor[6] = { 220.0, 246.94, 261.63, 293.66, 329.63, 392.0 };
    for (int i = 0; i < 40; i++)                           // mournful piano-ish motif, act 1-2
        s.push_back({ sec[0] + 1.2 + i * 1.31, 1.1, minor[(i * 7 / 3) % 6] * (i % 3 ? 1 : 0.5), 0.07, true });
    for (int i = 0; i < 12; i++) {                         // chant melody in the ritual
        double f[5] = { 196.0, 220.0, 233.08, 261.63, 146.83 };
        s.push_back({ sec[5] + 0.5 + i * 1.05, 0.9, f[i % 5], 0.11, true });
        s.push_back({ sec[5] + 0.5 + i * 1.05, 0.28, 68.0, 0.30, true });   // kendang thump
    }
    double t0 = sec[6], t1 = sec[8] + 14;                  // heartbeat under the dark act
    for (double t = t0; t < t1; t += 0.72) {
        s.push_back({ t, 0.20, 50.0, 0.40, true });
        s.push_back({ t + 0.22, 0.16, 46.0, 0.28, true });
    }
    for (double off : { 6.5, 9.5, 13.2, 18.0, 19.6 })      // clash hits through the duel
        s.push_back({ sec[7] + off, 0.35, 40.0, 0.5, true });
    s.push_back({ sec[7] + 17.7, 4.0, 65.41, 0.30, false });   // beam drone (C2)
    s.push_back({ sec[7] + 17.7, 4.0, 130.81, 0.18, false });
    s.push_back({ sec[9] + 0.8, 5.5, 220.0, 0.12, false });    // dawn chord
    s.push_back({ sec[9] + 0.8, 5.5, 277.18, 0.09, false });
    s.push_back({ sec[9] + 0.8, 5.5, 329.63, 0.07, false });
    s.push_back({ sec[10] + 9.5, 0.7, 43.65, 0.5, true });     // the twist sting
    for (int i = 0; i < 12; i++)                           // music-box credits
        s.push_back({ sec[11] + 1.0 + i * 0.62, 0.9, minor[(i * 5 / 2) % 6] * 2, 0.08, true });

    out.push_back(std::move(c));
}

} // namespace

int main(int argc, const char** argv) { return runCli(argc, argv, registerComps); }
